def network_pred(A, target_color, seeds):
 out=A.copy();dists={}
 for col in seeds:
  dist=np.full(A.shape,999);q=deque()
  for r,c in zip(*np.where(A==target_color)):
   if any(0<=r+dr<A.shape[0] and 0<=c+dc<A.shape[1] and A[r+dr,c+dc]==col for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]):
    dist[r,c]=1;q.append((r,c))
  while q:
   r,c=q.popleft()
   for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
    nr,nc=r+dr,c+dc
    if 0<=nr<A.shape[0] and 0<=nc<A.shape[1] and A[nr,nc]==target_color and dist[nr,nc]>dist[r,c]+1:
     dist[nr,nc]=dist[r,c]+1;q.append((nr,nc))
  dists[col]=dist
 for r,c in zip(*np.where(A==target_color)):
  vals=[dists[col][r,c] for col in seeds]
  m=min(vals)
  if vals.count(m)==1:out[r,c]=seeds[vals.index(m)]
 return out,dists
